import type {
	ConversationEvent,
	ConversationRole,
	JsonValue,
	ProtocolError,
	UIAction,
	UIDocument,
} from "./events";

export interface ConversationMessageState {
	id: string;
	role: ConversationRole;
	text: string;
	completed: boolean;
}

export interface AudioStreamState {
	id: string;
	messageId?: string;
	role: "user" | "assistant";
	encoding: string;
	sampleRate?: number;
	chunks: string[];
}

export interface TranscriptState {
	id: string;
	messageId?: string;
	role: "user" | "assistant";
