import { describe, expect, test } from "bun:test";

import {
  REQUIRED_CONTRAST,
  contrastRatio,
  cssVariables,
  exportDesignContract,
  keatingDesignContract,
  terminalDesignProfile,
  terminalStateText,
  validateDesignContract,
} from "../src/index.js";

describe("Keating design contract", () => {
  test("contains every required semantic role and valid accessibility baseline", () => {
    const result = validateDesignContract();
    expect(result).toEqual({ ok: true, errors: [] });
  });

  test("keeps normal and large text contrast above their respective thresholds", () => {
    for (const theme of ["light", "dark"] as const) {
      const colors = keatingDesignContract.themes[theme].colors;
      for (const requirement of REQUIRED_CONTRAST) {
        expect(contrastRatio(colors[requirement.foreground], colors[requirement.background])).toBeGreaterThanOrEqual(requirement.threshold);
      }
    }
  });

  test("exports contract and CSS variables deterministically", () => {
    expect(exportDesignContract()).toBe(exportDesignContract());
    expect(cssVariables("light")).toBe(cssVariables("light"));
    expect(cssVariables("light")).toContain("--keating-accent: #047857;");
    expect(cssVariables("dark")).toContain("--keating-accent: #4be388;");
  });

  test("terminal profiles degrade color without losing textual state", () => {
    const truecolor = terminalDesignProfile("dark", "truecolor", "unicode");
    expect(truecolor.colors.accent?.truecolor).toBe("#4be388");
    expect(terminalStateText("error", truecolor)).toContain("Error");

    const ansi256 = terminalDesignProfile("light", "ansi256", "unicode");
    expect(ansi256.colors.accent?.ansi256).toBe(35);

    const ansi16 = terminalDesignProfile("light", "ansi16", "unicode");
    expect(ansi16.colors.danger?.ansi16).toBe(1);

    const plainAscii = terminalDesignProfile("light", "none", "ascii");
    expect(plainAscii.colors.accent).toBeUndefined();
    expect(terminalStateText("success", plainAscii)).toBe("OK Success");
    expect(terminalStateText("disabled", plainAscii)).toBe("- Unavailable");
  });
});

/** Browser-, native-, and terminal-neutral semantic design vocabulary. */

export const DESIGN_CONTRACT_VERSION = 1 as const;

