const ARTIFACT_KINDS = new Set<ArtifactKind>([
  "note", "explanation", "study-plan", "lesson-map", "quiz", "deck", "image", "animation", "verification", "document", "other",
]);
const ARTIFACT_FORMATS = new Set<ArtifactFormat>(["markdown", "mermaid", "quiz", "openui", "image", "video", "json", "text"]);
const GOAL_STEP_STATUSES = new Set<GoalStepStatus>(["not_started", "in_progress", "done"]);

function isTimestamp(value: unknown): value is string {
  return typeof value === "string" && value.trim().length > 0 && Number.isFinite(Date.parse(value));
}

function hasId(value: unknown): value is string {
  return typeof value === "string" && value.trim().length > 0;
}

export function validateLearnerArtifact(value: unknown): value is LearnerArtifact {
  if (!value || typeof value !== "object" || Array.isArray(value)) return false;
  const artifact = value as Partial<LearnerArtifact>;
  if (!hasId(artifact.id) || !ARTIFACT_KINDS.has(artifact.kind as ArtifactKind)
    || !ARTIFACT_FORMATS.has(artifact.format as ArtifactFormat)
    || typeof artifact.title !== "string" || !isTimestamp(artifact.createdAt) || !isTimestamp(artifact.updatedAt)
    || (artifact.content !== undefined && typeof artifact.content !== "string")
    || (artifact.sourceSessionId !== undefined && !hasId(artifact.sourceSessionId))
    || (artifact.sourceMessageId !== undefined && !hasId(artifact.sourceMessageId))) return false;
  if (!artifact.attachment) return true;
  const attachment = artifact.attachment;
  if (!hasId(attachment.id) || typeof attachment.mimeType !== "string" || !attachment.mimeType.trim()
    || typeof attachment.sizeBytes !== "number" || !Number.isSafeInteger(attachment.sizeBytes) || attachment.sizeBytes < 0) return false;
  if (attachment.remoteUrl !== undefined) {
    try { new URL(attachment.remoteUrl); } catch { return false; }
  }
  return true;
}

export function validateLearnerGoal(value: unknown): value is LearnerGoal {
  if (!value || typeof value !== "object" || Array.isArray(value)) return false;
  const goal = value as Partial<LearnerGoal>;
  if (!hasId(goal.id) || typeof goal.title !== "string" || typeof goal.description !== "string"
    || !isTimestamp(goal.updatedAt) || !Array.isArray(goal.steps)) return false;
  const ids = new Set<string>();
  return goal.steps.every((step) => {
    if (!step || typeof step !== "object" || ids.has(step.id) || !hasId(step.id)
      || typeof step.title !== "string" || !GOAL_STEP_STATUSES.has(step.status)
      || !Array.isArray(step.successCriteria) || !step.successCriteria.every((criterion) => typeof criterion === "string")) return false;
    ids.add(step.id);
    return true;
  });
}

export function validateLearnerQuestionCheck(value: unknown): value is LearnerQuestionCheck {
  if (!value || typeof value !== "object" || Array.isArray(value)) return false;
  const check = value as Partial<LearnerQuestionCheck>;
  return hasId(check.id) && typeof check.topic === "string" && typeof check.question === "string"
    && typeof check.answer === "string" && isTimestamp(check.createdAt)
    && (check.score === undefined || (typeof check.score === "number" && Number.isFinite(check.score) && check.score >= 0 && check.score <= 1))
    && (check.grading === "auto" || check.grading === "model" || check.grading === "pending")
    && (check.misconception === undefined || typeof check.misconception === "string")
    && (check.sessionId === undefined || hasId(check.sessionId));
}

export function validateLearnerQuizResult(value: unknown): value is LearnerQuizResult {
  if (!value || typeof value !== "object" || Array.isArray(value)) return false;
  const quiz = value as Partial<LearnerQuizResult>;
  if (!hasId(quiz.id) || typeof quiz.topic !== "string" || !isTimestamp(quiz.createdAt)
