   131	/** Reject secrets and local workspace bytes even when nested in arbitrary metadata. */
   132	export function assertPortableDataSafe(value: unknown, path = "payload"): void {
   133	  if (Array.isArray(value)) {
   134	    value.forEach((entry, index) => assertPortableDataSafe(entry, `${path}[${index}]`));
   135	    return;
   136	  }
   137	  if (!value || typeof value !== "object") return;
