   154	    && Array.isArray(data.goals) && data.goals.every(validateLearnerGoal)
   155	    && Array.isArray(data.questionChecks) && data.questionChecks.every(validateLearnerQuestionCheck)
   156	    && Array.isArray(data.quizResults) && data.quizResults.every(validateLearnerQuizResult)
