   163	  const sessionsById = new Map(portable.sessions.map((session) => [session.id, session]));
   164	  if (sessionsById.size !== portable.sessions.length) return false;
   165	  for (const session of portable.sessions) {
   166	    if (!session.parentSessionId) continue;
   167	    const parent = sessionsById.get(session.parentSessionId);
   168	    if (!parent || !session.forkedFromMessageId
   169	      || !parent.messages.some((message) => message.id === session.forkedFromMessageId)) return false;
   170	  }
