   212	export interface DatedRecord {
   213	  id: string;
   214	  updatedAt?: string;
   215	  createdAt?: string;
   216	}
   217	
   218	function recordDate(record: DatedRecord): string {
   219	  return record.updatedAt ?? record.createdAt ?? "";
   220	}
   221	
   222	function stableRecordJson(record: DatedRecord): string {
   223	  const sort = (value: unknown): unknown => {
   224	    if (Array.isArray(value)) return value.map(sort);
   225	    if (!value || typeof value !== "object") return value;
   226	    return Object.fromEntries(Object.entries(value as Record<string, unknown>)
   227	      .sort(([left], [right]) => left.localeCompare(right))
   228	      .map(([key, entry]) => [key, sort(entry)]));
   229	  };
   230	  return JSON.stringify(sort(record));
   231	}
   232	
   233	/** Last update wins; equal timestamps use canonical JSON so merges are deterministic. */
   234	export function mergeDatedRecords<T extends DatedRecord>(...lists: ReadonlyArray<ReadonlyArray<T>>): T[] {
   235	  const records = new Map<string, T>();
   236	  for (const list of lists) {
   237	    for (const candidate of list) {
   238	      const current = records.get(candidate.id);
   239	      if (!current
   240	        || recordDate(candidate) > recordDate(current)
   241	        || (recordDate(candidate) === recordDate(current) && stableRecordJson(candidate) > stableRecordJson(current))) {
   242	        records.set(candidate.id, structuredClone(candidate));
   243	      }
   244	    }
   245	  }
   246	  return [...records.values()].sort((left, right) =>
   247	    recordDate(left).localeCompare(recordDate(right)) || left.id.localeCompare(right.id));
   248	}
