   254	  const generatedAt = left.generatedAt >= right.generatedAt ? left.generatedAt : right.generatedAt;
   255	  const profile = left.learnerProfile.sessionsCount >= right.learnerProfile.sessionsCount
   256	    ? left.learnerProfile
   257	    : right.learnerProfile;
   258	  return {
   259	    generatedAt,
   260	    sessions: mergeDatedRecords(left.sessions, right.sessions),
   261	    artifacts: mergeDatedRecords(left.artifacts, right.artifacts),
   262	    goals: mergeDatedRecords(left.goals, right.goals),
   263	    questionChecks: mergeDatedRecords(left.questionChecks, right.questionChecks),
   264	    quizResults: mergeDatedRecords(left.quizResults, right.quizResults),
   265	    decks: mergeDatedRecords(left.decks, right.decks),
   266	    cardReviews: mergeDatedRecords(left.cardReviews, right.cardReviews),
   267	    learnerProfile: structuredClone(profile),
   268	  };
