   346	  if (typeof session.id !== "string" || !session.id.trim()
   347	    || typeof session.title !== "string"
   348	    || !isTimestamp(session.createdAt)
   349	    || !isTimestamp(session.updatedAt)
   350	    || typeof session.activeBranchId !== "string"
