import { app, BrowserWindow } from "electron";
import { randomBytes } from "node:crypto";
import { existsSync, readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";
import {
	P2PStore,
	createP2PStorageBackend,
	type StorageBackendLike,
} from "@keating/p2p-core";
import { registerP2PIpc, type P2PBackendBridge } from "./ipc.js";
import {
	startPackagedNitro,
	type NitroRuntime,
} from "./nitro-runtime.js";
import { resolveDesktopRuntimePaths } from "./runtime-paths.js";

const __dirname = dirname(fileURLToPath(import.meta.url));
let nitroRuntime: NitroRuntime | null = null;
let shuttingDown = false;

/**
 * Load or create the per-user 32-byte secret that derives the swarm topic and
 * this device's writable core namespace.
 *
 * Resolution order:
 *  1. KEATING_USER_SECRET hex env var (lets you pair against a known seeder).
 *  2. A file at `${userData}/keating-user-secret.bin`. Created on first run
 *     with 32 bytes from sodium `crypto_randombytes_buf`.
 */
function loadUserSecret(): Uint8Array {
	const hex = process.env["KEATING_USER_SECRET"];
	if (hex && hex.trim().length > 0) {
		const trimmed = hex.trim();
		if (!/^[0-9a-fA-F]+$/.test(trimmed)) {
			throw new Error("KEATING_USER_SECRET must be hex-encoded");
		}
		const buf = Buffer.from(trimmed, "hex");
		if (buf.length !== 32) {
			throw new Error(
				`KEATING_USER_SECRET must be 32 bytes (got ${buf.length})`,
			);
		}
		return new Uint8Array(buf);
	}

	const userData = app.getPath("userData");
	const secretPath = join(userData, "keating-user-secret.bin");
	if (existsSync(secretPath)) {
		const raw = readFileSync(secretPath);
		if (raw.length !== 32) {
			throw new Error(
				`keating-user-secret.bin must be 32 bytes (got ${raw.length})`,
			);
		}
		return new Uint8Array(raw);
	}

	// First run: ensure userData exists, then generate and persist.
	try {
		mkdirSync(userData, { recursive: true });
	} catch {
		// ignore — likely already exists
	}
	const out = randomBytes(32);
	writeFileSync(secretPath, out);
	return out;
}

async function createWindow(): Promise<void> {
	const window = new BrowserWindow({
		width: 1200,
		height: 800,
		webPreferences: {
			preload: join(__dirname, "preload.js"),
			contextIsolation: true,
			nodeIntegration: false,
			sandbox: true,
		},
	});

	// Boot the P2P store in the main process and expose it to the renderer
	// strictly through the typed IPC bridge.
	const userSecret = loadUserSecret();
	const store = await P2PStore.open({
		storageDir: join(app.getPath("userData"), "p2p"),
		userSecret,
		label: `desktop:${process.platform}`,
	});

	const backend: StorageBackendLike = createP2PStorageBackend(store);
	const bridge: P2PBackendBridge = {
		...backend,
		batch: (mutations) => store.batch(mutations),
		stats: () => store.stats(),
	};
	registerP2PIpc(window, bridge);

	app.on("before-quit", () => {
		void store.close();
	});

	const devServer = process.env["KEATING_DEV_SERVER"];
	if (devServer) {
		await window.loadURL(devServer);
		return;
	}

	const runtime = await ensurePackagedNitro();
	await window.loadURL(new URL("/chat", runtime.origin).toString());
}

async function ensurePackagedNitro(): Promise<NitroRuntime> {
	if (nitroRuntime) return nitroRuntime;

	const paths = resolveDesktopRuntimePaths({
		isPackaged: app.isPackaged,
		moduleDir: __dirname,
		resourcesPath: process.resourcesPath,
		userData: app.getPath("userData"),
	});
	nitroRuntime = await startPackagedNitro(paths);
	return nitroRuntime;
}

async function shutdownPackagedNitro(): Promise<void> {
	const runtime = nitroRuntime;
	nitroRuntime = null;
	if (runtime) await runtime.stop();
}

app.whenReady()
	.then(async () => {
		await createWindow();
		app.on("activate", () => {
			if (BrowserWindow.getAllWindows().length === 0) void createWindow();
		});
	})
	.catch((error) => {
		console.error("Keating desktop failed to start:", error);
		app.quit();
	});

app.on("before-quit", (event) => {
	if (shuttingDown) return;
	shuttingDown = true;
	event.preventDefault();
	void shutdownPackagedNitro().finally(() => app.quit());
});

app.on("window-all-closed", () => {
	if (process.platform !== "darwin") app.quit();
});
import { spawn as nodeSpawn, type ChildProcess, type SpawnOptions } from "node:child_process";
import { createServer } from "node:net";
import { access, mkdir } from "node:fs/promises";
import type { DesktopRuntimePaths } from "./runtime-paths.js";
import { nitroEnvironment } from "./runtime-paths.js";

const LOOPBACK_HOST = "127.0.0.1";
const DEFAULT_READY_TIMEOUT_MS = 15_000;
const DEFAULT_READY_INTERVAL_MS = 100;
const DEFAULT_STOP_TIMEOUT_MS = 5_000;

type SpawnNitro = (
	command: string,
	args: readonly string[],
	options: SpawnOptions,
) => ChildProcess;

interface ReadinessResponse {
	ok: boolean;
}

export interface ReadinessOptions {
	timeoutMs?: number;
	intervalMs?: number;
	fetchImpl?: (input: string, init?: RequestInit) => Promise<ReadinessResponse>;
	now?: () => number;
	sleep?: (milliseconds: number) => Promise<void>;
}

export interface StopOptions {
	timeoutMs?: number;
	waitForExit?: (child: ChildProcess, timeoutMs: number) => Promise<void>;
}

export interface StartNitroOptions {
	executable?: string;
	spawn?: SpawnNitro;
	findPort?: () => Promise<number>;
	waitForReady?: (origin: string) => Promise<void>;
	parentEnvironment?: NodeJS.ProcessEnv;
}

export interface NitroRuntime {
	origin: string;
	child: ChildProcess;
	stop(): Promise<void>;
}

function pause(milliseconds: number): Promise<void> {
	return new Promise((resolve) => setTimeout(resolve, milliseconds));
}

/** Reserve an ephemeral loopback port for the child process startup. */
export async function findAvailableLoopbackPort(): Promise<number> {
	return await new Promise<number>((resolve, reject) => {
		const server = createServer();
		server.once("error", reject);
		server.listen({ host: LOOPBACK_HOST, port: 0 }, () => {
			const address = server.address();
			if (!address || typeof address === "string") {
				server.close(() => reject(new Error("Could not resolve an ephemeral loopback port.")));
				return;
			}
			server.close((error) => (error ? reject(error) : resolve(address.port)));
		});
	});
}

/**
 * Poll a same-origin health route until the child is serving requests. Each
 * probe is aborted at the remaining deadline so a stalled socket cannot make
 * startup exceed the caller's bounded timeout.
 */
export async function waitForNitroReady(
	origin: string,
	options: ReadinessOptions = {},
): Promise<void> {
	const timeoutMs = options.timeoutMs ?? DEFAULT_READY_TIMEOUT_MS;
	const intervalMs = options.intervalMs ?? DEFAULT_READY_INTERVAL_MS;
	const now = options.now ?? Date.now;
	const sleep = options.sleep ?? pause;
	const fetchImpl = options.fetchImpl ?? ((input, init) => fetch(input, init));
	const deadline = now() + timeoutMs;
	const healthUrl = new URL("/api/courses/session", origin).toString();
	let lastFailure = "no response";

	while (now() <= deadline) {
		const remaining = Math.max(1, deadline - now());
		const controller = new AbortController();
		const timer = setTimeout(() => controller.abort(), remaining);
		try {
			const response = await fetchImpl(healthUrl, { signal: controller.signal });
			if (response.ok) return;
			lastFailure = `HTTP response was not OK`;
		} catch (error) {
			lastFailure = error instanceof Error ? error.message : String(error);
		} finally {
			clearTimeout(timer);
		}

		if (now() >= deadline) break;
		await sleep(Math.min(intervalMs, Math.max(0, deadline - now())));
	}

	throw new Error(`Keating local server did not become ready within ${timeoutMs}ms (${lastFailure}).`);
}

function waitForChildExit(child: ChildProcess, timeoutMs: number): Promise<void> {
	if (child.exitCode !== null) return Promise.resolve();
	return new Promise((resolve, reject) => {
		const timer = setTimeout(() => {
			cleanup();
			reject(new Error(`Nitro child did not exit within ${timeoutMs}ms.`));
		}, timeoutMs);
		const onExit = () => {
			cleanup();
			resolve();
		};
		const onError = (error: Error) => {
			cleanup();
			reject(error);
		};
		const cleanup = () => {
			clearTimeout(timer);
			child.removeListener("exit", onExit);
			child.removeListener("error", onError);
		};
		child.once("exit", onExit);
		child.once("error", onError);
	});
}

/** Stop the child gracefully, then force termination only after its deadline. */
export async function stopNitroChild(
	child: ChildProcess,
	options: StopOptions = {},
): Promise<void> {
	if (child.exitCode !== null) return;
	const timeoutMs = options.timeoutMs ?? DEFAULT_STOP_TIMEOUT_MS;
	const waitForExit = options.waitForExit ?? waitForChildExit;
	child.kill("SIGTERM");
	try {
		await waitForExit(child, timeoutMs);
		return;
	} catch {
		if (child.exitCode !== null) return;
	}

	child.kill("SIGKILL");
	await waitForExit(child, timeoutMs);
}

/**
 * Launch the staged Nitro node-server output in an Electron-as-Node child.
 * The renderer never receives this process environment or its mutable paths.
 */
export async function startPackagedNitro(
	paths: DesktopRuntimePaths,
	options: StartNitroOptions = {},
): Promise<NitroRuntime> {
	await Promise.all([
		access(paths.serverEntry),
		mkdir(paths.stateRoot, { recursive: true }),
		mkdir(paths.coursesStorageDir, { recursive: true }),
		mkdir(paths.coursesPearStorageDir, { recursive: true }),
	]);

	const findPort = options.findPort ?? findAvailableLoopbackPort;
	const port = await findPort();
	const origin = `http://${LOOPBACK_HOST}:${port}`;
	const spawn = options.spawn ?? nodeSpawn;
	const child = spawn(options.executable ?? process.execPath, [paths.serverEntry], {
		cwd: paths.runtimeRoot,
		env: nitroEnvironment(paths, port, options.parentEnvironment),
		// Nitro is fully self-contained at this point. Ignoring its streams avoids a
		// stalled child if an unattended pipe fills before Electron can exit.
		stdio: "ignore",
	});

	const waitForReady = options.waitForReady ?? ((runtimeOrigin: string) => waitForNitroReady(runtimeOrigin));
	try {
		await waitForReady(origin);
	} catch (error) {
		await stopNitroChild(child).catch(() => {});
		throw error;
	}

	return {
		origin,
		child,
		stop: () => stopNitroChild(child),
	};
}
import { join } from "node:path";

export interface DesktopRuntimePathOptions {
	isPackaged: boolean;
	moduleDir: string;
	resourcesPath: string;
	userData: string;
}

export interface DesktopRuntimePaths {
	/** Read-only Nitro output shipped beside the Electron application. */
	runtimeRoot: string;
	serverEntry: string;
	/** Mutable state must never be written to app resources or ASAR. */
	stateRoot: string;
	coursesStorageDir: string;
	coursesPearStorageDir: string;
}

/**
 * Resolve all filesystem boundaries used by the packaged local server. In a
 * development build the staging script places Nitro beneath dist/; packaged
 * builds receive that exact tree as an Electron extraResource at resources/nitro.
 */
export function resolveDesktopRuntimePaths(
	options: DesktopRuntimePathOptions,
): DesktopRuntimePaths {
	const runtimeRoot = options.isPackaged
		? join(options.resourcesPath, "nitro")
		: join(options.moduleDir, "nitro");
	const stateRoot = join(options.userData, "nitro");

	return {
		runtimeRoot,
		serverEntry: join(runtimeRoot, "server", "index.mjs"),
		stateRoot,
		coursesStorageDir: join(stateRoot, "courses"),
		coursesPearStorageDir: join(stateRoot, "courses-pear"),
	};
}

export function nitroEnvironment(
	paths: DesktopRuntimePaths,
	port: number,
	parentEnvironment: NodeJS.ProcessEnv = process.env,
): NodeJS.ProcessEnv {
	if (!Number.isInteger(port) || port < 1 || port > 65_535) {
		throw new Error(`Nitro loopback port must be an integer from 1 to 65535 (got ${port}).`);
	}

	return {
		...parentEnvironment,
		// Run the Electron executable as a Node child so the bundled Nitro output
		// shares Electron's Node ABI without opening another Chromium process.
		ELECTRON_RUN_AS_NODE: "1",
		NITRO_HOST: "127.0.0.1",
		NITRO_PORT: String(port),
		KEATING_COURSES_STORAGE_DIR: paths.coursesStorageDir,
		KEATING_COURSES_PEAR_STORAGE_DIR: paths.coursesPearStorageDir,
	};
}
