    const reordered = { "ä": 2, z: 3, A: { "β": 2, a: 1 } };
    expect(codepointCompare("z", "ä")).toBeLessThan(0);
    expect(stableCanonicalJson(reordered)).toBe('{"A":{"a":1,"β":2},"z":3,"ä":2}');
