 45 │ function phaseIndex(phase: unknown): number {
 46 │   return typeof phase === "string" ? MIGRATION_PHASES.indexOf(phase as MigrationPhase) : -1;
 47 │ }
 48 │ 
 49 │ function isVersion(value: unknown): value is number {
 50 │   return typeof value === "number" && Number.isSafeInteger(value) && value > 0;
 51 │ }
 52 │ 
 53 │ function parseTimestamp(value: string, label: string): number {
 54 │   if (!UTC_TIMESTAMP.test(value)) throw new Error(`${label} must be a UTC timestamp.`);
 55 │   const milliseconds = Date.parse(value);
 56 │   const normalized = value.includes(".") ? value : value.replace("Z", ".000Z");
 57 │   if (!Number.isFinite(milliseconds) || new Date(milliseconds).toISOString() !== normalized) {
 58 │     throw new Error(`${label} must be a calendar-valid UTC timestamp.`);
 59 │   }
 60 │   return milliseconds;
 61 │ }
