 67 │ function assertStartInput(input: StartMigrationInput): void {
 68 │   if (!CONTRACT_ID.test(input.id)) throw new Error("Migration journal id is invalid.");
 69 │   if (!isVersion(input.sourceVersion) || !isVersion(input.targetVersion)
 70 │     || input.targetVersion < input.sourceVersion) {
 71 │     throw new Error("Migration journal versions are invalid.");
 72 │   }
 73 │   if (!SHA_256_HEX.test(input.digest)) throw new Error("Migration journal digest is invalid.");
 74 │ }
