 80 │ function entryFromRow(row: MigrationRow): MigrationJournalEntry {
 81 │   assertStartInput({
 82 │     id: row.id,
 83 │     sourceVersion: row.source_version,
 84 │     targetVersion: row.target_version,
 85 │     digest: row.digest,
 86 │   });
 87 │   assertPhase(row.phase);
 88 │   const createdAt = parseTimestamp(row.created_at, "Migration created time");
 89 │   const updatedAt = parseTimestamp(row.updated_at, "Migration updated time");
 90 │   if (updatedAt < createdAt) throw new Error("Migration updated time cannot precede creation time.");
 91 │   const completedAt = row.completed_at === null
 92 │     ? null
 93 │     : parseTimestamp(row.completed_at, "Migration completion time");
 94 │   if (completedAt !== null && completedAt < updatedAt) {
 95 │     throw new Error("Migration completion time cannot precede update time.");
 96 │   }
 97 │   if (row.phase === "completed" && row.completed_at === null) {
 98 │     throw new Error("Completed migration is missing its completion time.");
 99 │   }
100 │   if (row.phase !== "completed" && row.completed_at !== null) {
101 │     throw new Error("Incomplete migration has a completion time.");
102 │   }
103 │   return {
104 │     id: row.id,
105 │     sourceVersion: row.source_version,
106 │     targetVersion: row.target_version,
107 │     digest: row.digest,
108 │     phase: row.phase,
109 │     createdAt: row.created_at,
110 │     updatedAt: row.updated_at,
111 │     ...(row.completed_at ? { completedAt: row.completed_at } : {}),
112 │   };
113 │ }
