115 │ async function readMigration(
116 │   executor: AsyncSqlExecutor,
117 │   id: string,
118 │ ): Promise<MigrationJournalEntry | null> {
119 │   const row = await executor.getFirstAsync<MigrationRow>(
120 │     "SELECT id, source_version, target_version, digest, phase, created_at, updated_at, completed_at FROM migration_journal WHERE id = ?;",
121 │     id,
122 │   );
123 │   return row ? entryFromRow(row) : null;
124 │ }
