133 │ /**
134 │  * Closed, one-step journal transitions make a crash recoverable: retrying the
135 │  * same phase returns the existing durable entry; backwards/skipped phases fail.
136 │  */
137 │ export class MigrationJournal {
138 │   constructor(
139 │     private readonly database: AsyncSqlDatabase,
140 │     private readonly now: MigrationClock = () => new Date().toISOString(),
141 │   ) {}
142 │ 
143 │   async get(id: string): Promise<MigrationJournalEntry | null> {
144 │     if (!CONTRACT_ID.test(id)) throw new Error("Migration journal id is invalid.");
145 │     return withExclusiveTransaction(this.database, (transaction) => readMigration(transaction, id));
146 │   }
147 │ 
148 │   async start(input: StartMigrationInput): Promise<MigrationJournalEntry> {
149 │     assertStartInput(input);
150 │     return withExclusiveTransaction(this.database, async (transaction) => {
151 │       const existing = await readMigration(transaction, input.id);
152 │       if (existing) {
153 │         assertSameMigration(existing, input);
154 │         return existing;
155 │       }
156 │       const timestamp = this.now();
157 │       assertClockTimestamp(timestamp);
158 │       await transaction.runAsync(
159 │         "INSERT INTO migration_journal (id, source_version, target_version, digest, phase, created_at, updated_at, completed_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?);",
160 │         input.id,
161 │         input.sourceVersion,
162 │         input.targetVersion,
163 │         input.digest,
164 │         "prepared",
165 │         timestamp,
166 │         timestamp,
167 │         null,
168 │       );
169 │       return {
170 │         ...input,
171 │         phase: "prepared",
172 │         createdAt: timestamp,
173 │         updatedAt: timestamp,
174 │       };
175 │     });
176 │   }
177 │ 
178 │   async advance(id: string, nextPhase: MigrationPhase): Promise<MigrationJournalEntry> {
179 │     if (!CONTRACT_ID.test(id)) throw new Error("Migration journal id is invalid.");
180 │     assertPhase(nextPhase);
181 │     return withExclusiveTransaction(this.database, async (transaction) => {
182 │       const existing = await readMigration(transaction, id);
183 │       if (!existing) throw new Error("Migration journal entry does not exist.");
184 │       const currentIndex = phaseIndex(existing.phase);
185 │       const nextIndex = phaseIndex(nextPhase);
186 │       if (nextIndex < currentIndex) throw new Error("Migration journal phase cannot regress.");
187 │       if (nextIndex === currentIndex) return existing;
188 │       if (nextIndex !== currentIndex + 1) throw new Error("Migration journal phase must advance one step.");
189 │ 
190 │       const timestamp = this.now();
191 │       const timestampMs = assertClockTimestamp(timestamp);
192 │       if (timestampMs < parseTimestamp(existing.updatedAt, "Migration updated time")) {
193 │         throw new Error("Migration clock cannot move backward.");
194 │       }
195 │       const completedAt = nextPhase === "completed" ? timestamp : null;
196 │       const result = await transaction.runAsync(
197 │         "UPDATE migration_journal SET phase = ?, updated_at = ?, completed_at = ? WHERE id = ? AND phase = ?;",
198 │         nextPhase,
199 │         timestamp,
200 │         completedAt,
201 │         id,
202 │         existing.phase,
203 │       );
204 │       if (result.changes !== 1) {
205 │         await readMigration(transaction, id);
206 │         throw new Error("Migration journal changed concurrently; retry from its durable phase.");
207 │       }
208 │       return {
209 │         ...existing,
210 │         phase: nextPhase,
211 │         updatedAt: timestamp,
212 │         ...(completedAt ? { completedAt } : {}),
213 │       };
214 │     });
215 │   }
216 │ }
