 38 │   async runAsync(source: string, ...params: SqlBindValue[]): Promise<{ changes: number; lastInsertRowId: number }> {
 39 │     this.calls.push(`run:${source}`);
 40 │     if (source.startsWith("INSERT INTO repository_meta")) {
 41 │       this.meta.set(String(params[0]), String(params[1]));
 42 │     } else if (source.startsWith("UPDATE repository_meta")) {
 43 │       this.meta.set(String(params[1]), String(params[0]));
 44 │     } else if (source.startsWith("INSERT INTO migration_journal")) {
 45 │       const [id, sourceVersion, targetVersion, digest, phase, createdAt, updatedAt, completedAt] = params;
 46 │       this.journal.set(String(id), {
 47 │         id: String(id), source_version: Number(sourceVersion), target_version: Number(targetVersion),
 48 │         digest: String(digest), phase: String(phase), created_at: String(createdAt),
 49 │         updated_at: String(updatedAt), completed_at: completedAt === null ? null : String(completedAt),
