61 │ export function validateAgentStream(events: unknown): events is AgentStreamEvent[] {
62 │   if (!Array.isArray(events) || !events.every(validateAgentStreamEvent) || !hasUniqueIds(events)) return false;
63 │   const calls = new Map<string, ToolCall>();
64 │   const callIdempotencyKeys = new Set<string>();
65 │   const resultCallIds = new Set<string>();
66 │   const resultIdempotencyKeys = new Set<string>();
67 │   const sequences = new Set<number>();
68 │   const turnId = events[0]?.turnId;
69 │   let previousSequence = -1;
70 │   let terminal = false;
71 │   for (const event of events) {
72 │     if (event.turnId !== turnId || terminal || sequences.has(event.sequence) || event.sequence <= previousSequence) return false;
73 │     sequences.add(event.sequence);
74 │     previousSequence = event.sequence;
75 │     if (event.type === "tool-call") {
76 │       if (calls.has(event.call.id) || callIdempotencyKeys.has(event.call.idempotencyKey)) return false;
77 │       calls.set(event.call.id, event.call);
78 │       callIdempotencyKeys.add(event.call.idempotencyKey);
79 │     }
80 │     if (event.type === "tool-result") {
81 │       const call = calls.get(event.result.toolCallId);
82 │       if (!call || call.idempotencyKey !== event.result.idempotencyKey
83 │         || resultCallIds.has(event.result.toolCallId)
