85 │       resultCallIds.add(event.result.toolCallId);
86 │       resultIdempotencyKeys.add(event.result.idempotencyKey);
87 │     }
88 │     if (event.type === "completed" || event.type === "cancelled") terminal = true;
89 │   }
90 │   return true;
