 24 │ class FakeDatabase implements AsyncSqlDatabase {
 25 │   readonly calls: string[] = [];
 26 │   readonly meta = new Map<string, string>();
 27 │   readonly journal = new Map<string, JournalRow>();
 28 │   exclusiveTransactions = 0;
 29 │   closeCalls = 0;
 30 │   failOn: string | undefined;
 31 │   crossConnectionMigrationInsert: ((row: JournalRow) => void) | undefined;
 32 │   migrationInsertFailure: Error | undefined;
 33 │   beforeMigrationUpdate: ((row: JournalRow) => void) | undefined;
 34 │   private transactionTail: Promise<void> = Promise.resolve();
 35 │ 
 36 │   async execAsync(source: string): Promise<void> {
 37 │     this.calls.push(`exec:${source}`);
 38 │     if (this.failOn && source.includes(this.failOn)) throw new Error("injected open failure");
 39 │   }
 40 │ 
 41 │   async runAsync(source: string, ...params: SqlBindValue[]): Promise<{ changes: number; lastInsertRowId: number }> {
 42 │     this.calls.push(`run:${source}`);
 43 │     if (source.startsWith("INSERT INTO repository_meta")) {
 44 │       this.meta.set(String(params[0]), String(params[1]));
 45 │     } else if (source.startsWith("UPDATE repository_meta")) {
 46 │       this.meta.set(String(params[1]), String(params[0]));
 47 │     } else if (source.startsWith("INSERT INTO migration_journal")) {
 48 │       const [id, sourceVersion, targetVersion, digest, phase, createdAt, updatedAt, completedAt] = params;
 49 │       const row = {
 50 │         id: String(id), source_version: Number(sourceVersion), target_version: Number(targetVersion),
 51 │         digest: String(digest), phase: String(phase), created_at: String(createdAt),
 52 │         updated_at: String(updatedAt), completed_at: completedAt === null ? null : String(completedAt),
 53 │       };
 54 │       this.crossConnectionMigrationInsert?.(row);
 55 │       if (this.journal.has(row.id)) {
 56 │         throw new Error("UNIQUE constraint failed: migration_journal.id");
 57 │       }
 58 │       if (this.migrationInsertFailure) throw this.migrationInsertFailure;
 59 │       this.journal.set(String(id), row);
 60 │     } else if (source.startsWith("UPDATE migration_journal")) {
 61 │       const [phase, updatedAt, completedAt, id, expectedPhase] = params;
 62 │       const row = this.journal.get(String(id));
 63 │       if (!row) throw new Error("missing journal row");
 64 │       this.beforeMigrationUpdate?.(row);
 65 │       if (row.phase !== String(expectedPhase)) return { changes: 0, lastInsertRowId: 0 };
 66 │       row.phase = String(phase);
 67 │       row.updated_at = String(updatedAt);
 68 │       row.completed_at = completedAt === null ? null : String(completedAt);
 69 │     }
 70 │     return { changes: 1, lastInsertRowId: 1 };
 71 │   }
 72 │ 
 73 │   async getFirstAsync<T>(source: string, ...params: SqlBindValue[]): Promise<T | null> {
 74 │     this.calls.push(`get:${source}`);
 75 │     if (source.includes("FROM repository_meta")) {
 76 │       const value = this.meta.get(String(params[0]));
 77 │       return value === undefined ? null : { value } as T;
 78 │     }
 79 │     if (source.includes("FROM migration_journal")) {
 80 │       const row = this.journal.get(String(params[0]));
 81 │       return row ? { ...row } as T : null;
 82 │     }
 83 │     return null;
 84 │   }
 85 │ 
 86 │   async withExclusiveTransactionAsync(task: (transaction: AsyncSqlExecutor) => Promise<void>): Promise<void> {
 87 │     this.exclusiveTransactions += 1;
 88 │     const previous = this.transactionTail;
 89 │     let release!: () => void;
 90 │     this.transactionTail = new Promise<void>((resolve) => {
 91 │       release = resolve;
 92 │     });
 93 │     await previous;
 94 │     try {
 95 │       await task(this);
 96 │     } finally {
 97 │       release();
 98 │     }
 99 │   }
100 │ 
101 │   async closeAsync(): Promise<void> {
102 │     this.closeCalls += 1;
103 │   }
104 │ }
