 1 │ /**
 2 │  * Small structural subset of Expo SQLite's asynchronous API. Keeping the
 3 │  * repository on this boundary makes its migration rules testable under Bun
 4 │  * without loading a native module.
 5 │  */
 6 │ export type SqlBindValue = string | number | boolean | null | Uint8Array;
 7 │ 
 8 │ export interface SqlRunResult {
 9 │   changes: number;
10 │   lastInsertRowId: number;
11 │ }
12 │ 
13 │ export interface AsyncSqlExecutor {
14 │   execAsync(source: string): Promise<void>;
15 │   runAsync(source: string, ...params: SqlBindValue[]): Promise<SqlRunResult>;
16 │   getFirstAsync<T>(source: string, ...params: SqlBindValue[]): Promise<T | null>;
17 │ }
18 │ 
19 │ export interface AsyncSqlDatabase extends AsyncSqlExecutor {
20 │   withExclusiveTransactionAsync(
21 │     task: (transaction: AsyncSqlExecutor) => Promise<void>,
22 │   ): Promise<void>;
23 │   closeAsync(): Promise<void>;
24 │ }
25 │ 
26 │ export interface AsyncSqliteDriver {
27 │   openDatabaseAsync(name: string): Promise<AsyncSqlDatabase>;
28 │ }
29 │ 
30 │ /** All repository mutations use Expo SQLite's exclusive async transaction. */
31 │ export function withExclusiveTransaction<T>(
32 │   database: AsyncSqlDatabase,
33 │   work: (transaction: AsyncSqlExecutor) => Promise<T>,
34 │ ): Promise<T> {
35 │   let result!: T;
36 │   let completed = false;
37 │   return database.withExclusiveTransactionAsync(async (transaction) => {
38 │     result = await work(transaction);
39 │     completed = true;
40 │   }).then(() => {
41 │     if (!completed) throw new Error("Exclusive transaction completed without invoking its callback.");
42 │     return result;
43 │   });
44 │ }
