139 │ /**
140 │  * Closed, one-step journal transitions make a crash recoverable: retrying the
141 │  * same phase returns the existing durable entry; backwards/skipped phases fail.
142 │  */
143 │ export class MigrationJournal {
144 │   constructor(
145 │     private readonly database: AsyncSqlDatabase,
146 │     private readonly now: MigrationClock = () => new Date().toISOString(),
147 │   ) {}
148 │ 
149 │   async get(id: string): Promise<MigrationJournalEntry | null> {
150 │     if (!CONTRACT_ID.test(id)) throw new Error("Migration journal id is invalid.");
151 │     return withExclusiveTransaction(this.database, (transaction) => readMigration(transaction, id));
152 │   }
153 │ 
154 │   async start(input: StartMigrationInput): Promise<MigrationJournalEntry> {
155 │     assertStartInput(input);
156 │     let lastError: unknown;
157 │     for (let attempt = 0; attempt < START_ATTEMPTS; attempt += 1) {
158 │       try {
159 │         return await withExclusiveTransaction(this.database, async (transaction) => {
160 │           const existing = await readMigration(transaction, input.id);
161 │           if (existing) {
162 │             assertSameMigration(existing, input);
163 │             return existing;
164 │           }
165 │           const timestamp = this.now();
166 │           assertClockTimestamp(timestamp);
167 │           await transaction.runAsync(
168 │             "INSERT INTO migration_journal (id, source_version, target_version, digest, phase, created_at, updated_at, completed_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?);",
169 │             input.id,
170 │             input.sourceVersion,
171 │             input.targetVersion,
172 │             input.digest,
173 │             "prepared",
174 │             timestamp,
175 │             timestamp,
176 │             null,
177 │           );
178 │           return {
179 │             ...input,
180 │             phase: "prepared",
181 │             createdAt: timestamp,
182 │             updatedAt: timestamp,
183 │           };
184 │         });
185 │       } catch (error) {
186 │         if (!isRecoverableInsertRace(error)) throw error;
187 │         lastError = error;
188 │       }
189 │     }
190 │     throw lastError;
191 │   }
192 │ 
193 │   async advance(id: string, nextPhase: MigrationPhase): Promise<MigrationJournalEntry> {
194 │     if (!CONTRACT_ID.test(id)) throw new Error("Migration journal id is invalid.");
195 │     assertPhase(nextPhase);
196 │     return withExclusiveTransaction(this.database, async (transaction) => {
197 │       const existing = await readMigration(transaction, id);
198 │       if (!existing) throw new Error("Migration journal entry does not exist.");
199 │       const currentIndex = phaseIndex(existing.phase);
200 │       const nextIndex = phaseIndex(nextPhase);
201 │       if (nextIndex < currentIndex) throw new Error("Migration journal phase cannot regress.");
202 │       if (nextIndex === currentIndex) return existing;
203 │       if (nextIndex !== currentIndex + 1) throw new Error("Migration journal phase must advance one step.");
204 │ 
205 │       const timestamp = this.now();
206 │       const timestampMs = assertClockTimestamp(timestamp);
207 │       if (timestampMs < parseTimestamp(existing.updatedAt, "Migration updated time")) {
208 │         throw new Error("Migration clock cannot move backward.");
209 │       }
210 │       const completedAt = nextPhase === "completed" ? timestamp : null;
211 │       const result = await transaction.runAsync(
212 │         "UPDATE migration_journal SET phase = ?, updated_at = ?, completed_at = ? WHERE id = ? AND phase = ?;",
213 │         nextPhase,
214 │         timestamp,
215 │         completedAt,
216 │         id,
217 │         existing.phase,
218 │       );
219 │       if (result.changes !== 1) {
220 │         await readMigration(transaction, id);
221 │         throw new Error("Migration journal changed concurrently; retry from its durable phase.");
222 │       }
223 │       return {
224 │         ...existing,
225 │         phase: nextPhase,
226 │         updatedAt: timestamp,
227 │         ...(completedAt ? { completedAt } : {}),
228 │       };
229 │     });
230 │   }
231 │ }
