 9 │ function adaptExpoExecutor(database: SQLiteDatabase): AsyncSqlExecutor {
10 │   return {
11 │     execAsync: (source) => database.execAsync(source),
12 │     runAsync: (source: string, ...params: SqlBindValue[]) => database.runAsync(source, ...params),
13 │     getFirstAsync: <T>(source: string, ...params: SqlBindValue[]) => database.getFirstAsync<T>(source, ...params),
14 │   };
15 │ }
