17 │ function adaptExpoDatabase(database: SQLiteDatabase): AsyncSqlDatabase {
18 │   return {
19 │     ...adaptExpoExecutor(database),
20 │     withExclusiveTransactionAsync: async (task) => {
21 │       await database.withExclusiveTransactionAsync(async (transaction) => {
22 │         await task(adaptExpoExecutor(transaction));
23 │       });
24 │     },
25 │     closeAsync: () => database.closeAsync(),
26 │   };
27 │ }
