104 │      * @param task An async function to execute within a transaction. Any queries inside the transaction must be executed on the `txn` object.
105 │      * The `txn` object has the same interfaces as the [`SQLiteDatabase`](#sqlitedatabase) object. You can use `txn` like a [`SQLiteDatabase`](#sqlitedatabase) object.
106 │      *
107 │      * @platform android
108 │      * @platform ios
109 │      * @platform macos
110 │      * @platform tvos
111 │      *
112 │      * @example
113 │      * ```ts
114 │      * db.withExclusiveTransactionAsync(async (txn) => {
115 │      *   await txn.execAsync('UPDATE test SET name = "aaa"');
116 │      * });
117 │      * ```
118 │      */
119 │     withExclusiveTransactionAsync(task: (txn: Transaction) => Promise<void>): Promise<void>;
120 │     /**
121 │      * Synchronous call to return whether the database is currently in a transaction.
122 │      */
155 │     async withExclusiveTransactionAsync(task) {
156 │         if (Platform.OS === 'web') {
157 │             throw new Error('withExclusiveTransactionAsync is not supported on web');
158 │         }
159 │         const transaction = await Transaction.createAsync(this);
160 │         let error;
161 │         try {
162 │             await transaction.execAsync('BEGIN');
163 │             await task(transaction);
164 │             await transaction.execAsync('COMMIT');
165 │         }
166 │         catch (e) {
167 │             await transaction.execAsync('ROLLBACK');
168 │             error = e;
169 │         }
170 │         finally {
171 │             await transaction.closeAsync();
172 │         }
173 │         if (error) {
174 │             throw error;
175 │         }
176 │     }
